  ('resume-studio', 'Resume Studio', 'Upload your resume and a job description to get an ATS score, a rewritten resume tailored to the job, and a matching cover letter.', 'Jobs & Careers', ARRAY['Resume', 'Document Tools'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('mock-interview-coach', 'Mock Interview Coach', 'Practise a real interview by voice or text for any role, with follow-up questions, scores for each answer and model answers.', 'Jobs & Careers', ARRAY['Interview Prep', 'Coaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('career-switch-planner', 'Career Switch Planner', 'Plan a move into a new field: target roles, transferable skills, skill gaps, learning path, portfolio projects and a 6-month switch plan.', 'Jobs & Careers', ARRAY['Career Planning', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('linkedin-profile-makeover', 'LinkedIn Profile Makeover', 'Upload your LinkedIn profile to get a rewritten headline, About, experience bullets, skills, featured ideas and a banner image.', 'Jobs & Careers', ARRAY['LinkedIn', 'Personal Branding'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('salary-negotiation-coach', 'Salary Negotiation Coach', 'Practise your salary talk with an AI recruiter, get your number and walk-away point, and leave with scripts for every pushback.', 'Jobs & Careers', ARRAY['Negotiation', 'Coaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('job-hunt-command-centre', 'Job Hunt Command Centre', 'Paste the jobs you are tracking to get a ranked shortlist, fit scores, tailored pitches, a follow-up schedule and a weekly plan.', 'Jobs & Careers', ARRAY['Job Search', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('campus-placement-prep', 'Campus Placement Prep', 'A placement prep plan for your branch and target companies: aptitude, technical topics, group discussion, HR answers and a day-by-day schedule.', 'Jobs & Careers', ARRAY['Placements', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['For Students']),
  ('government-job-exam-planner', 'Government Job Exam Planner', 'A study plan for SSC, banking, railway, UPSC or state PSC exams: syllabus split, daily timetable, mock tests and revision cycles.', 'Jobs & Careers', ARRAY['Government Exams', 'Study Plans'], 'featured', true, false, false, NULL, 0, ARRAY['For Students']),
  ('portfolio-website-builder', 'Portfolio Website Builder', 'Get a complete portfolio website for your work: structure, all page copy, project case studies and a ready-to-host HTML page.', 'Jobs & Careers', ARRAY['Portfolio', 'Website'], 'featured', true, false, false, NULL, 0, ARRAY['Content Creation']),
  ('case-interview-coach', 'Case Interview Coach', 'Practise consulting and product case interviews live: market sizing, profitability and product cases, scored on structure and maths.', 'Jobs & Careers', ARRAY['Interview Prep', 'Coaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('coding-interview-coach', 'Coding Interview Coach', 'Practise coding interviews: problems at your level, hints instead of answers, code reviews, complexity checks and a study plan.', 'Jobs & Careers', ARRAY['Interview Prep', 'Programming'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('freelancer-launch-kit', 'Freelancer Launch Kit', 'Launch as a freelancer: niche and offer, packages and pricing, profile copy, proposal template, contract checklist and client hunting plan.', 'Jobs & Careers', ARRAY['Freelancing', 'Business'], 'featured', true, false, false, NULL, 0, ARRAY['Startups & Strategy']),
  ('self-review-writer', 'Self-Review Writer', 'Paste your work notes, goals and feedback to get a strong self-appraisal with achievements, impact, ratings and next-year goals.', 'Jobs & Careers', ARRAY['Appraisal', 'Writing'], 'featured', true, false, false, NULL, 0, ARRAY['HR & Staffing']),
  ('new-manager-kit', 'New Manager Kit', 'Your first 90 days as a manager: team map, one-on-one guide, feedback scripts, delegation plan, meeting rhythm and hard conversations.', 'Jobs & Careers', ARRAY['Management', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['HR & Staffing']),
