  ('workplace-conflict-coach', 'Workplace Conflict Coach', 'Talk through a conflict with a boss, colleague or team member, practise the conversation, and leave with a plan and exact words.', 'Jobs & Careers', ARRAY['Workplace', 'Coaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
